from historiansim.plants.base import PlantDescription,Section

def describe(cfg):return PlantDescription(title='Generic 1,500 metric tonne-force continuous strip line',intro=['Simulation only. Continuous strip passes through ten die stations at no more than ten strokes/minute; the first part leaves the tenth stroke.'],sections=[Section('Connected equipment',['Reel and counted two-minute coil replacements supply a finite slack loop through a seven-roll straightener (50mm radius, gap95% of thickness, steel E210GPa). A finite-motion feeder checks actual shaft versus strip travel before permitting forming. Ten station presence/load instruments and four corner tonnage channels observe the die.','A50L lube reservoir supplies ten timed branches, with90% return; low pressure/inventory inhibits forming. Shaker/conveyor offal removal is independent of product rejection. Product passes through finite discharge/washer/packing queues.','The washer resolves water makeup/evaporation, actual heater duty, part/water heat exchange and cleaning dose during residence. A declared synthetic manual visual inspection accepts/rejects at exit. Packing rate varies by10%, with finite customer containers and changeovers. True cleaning dose is not exported.']),Section('Engineering and acquisition boundaries',['Station forces and presence are synthetic direct instrument assumptions; counters and phase are PLC derived. Private mass, energy and water ledgers never become public instrument tags. Generic values are not manufacturer calibration.','A triangular force versus ram displacement integrates to declared work. Electrical power/current and averaged cycle energy share drive efficiency and power factor. The envelope is not a rigid-crank or machine-safety qualification.','Numerical integration0.1s, native acquisition1s and compressed historian export are distinct clocks. Cycle/feed/product/packing events preserve native journal timestamps. Digital encoder quantization is retained without arbitrary colored noise. Native validation failures remain visible; explicit practice data is UNVALIDATED.']), 'tags','instruments','files'],tag_notes={},calc_definitions=[],calc_notes=[],instrument_notes=['Public observations preserve native quality. Sensor faults corrupt acquisition without changing physical stock or part ledgers.'])
